const data=window.CITOYEN;
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const validIds=new Set(data.lessons.map(l=>l.id));
const P=window.CitoyenProgress;
let accountId=null,storageOK=true,syncText='',state=P.clean({},validIds),lastSaved;
try {state=P.clean(JSON.parse(localStorage.getItem(P.key(null))||localStorage.getItem('citoyen-learning-v1')||'{}'),validIds)} catch {storageOK=false}
lastSaved=structuredClone(state);
const main=$('main'),dialog=$('#lesson-dialog');let view='parcours',themeId=null,lessonState=null,deck={ids:[],index:0,flipped:false,filter:'all',reviewOnly:false},quiz=null,quizFilter='all',repereTab='timeline',eventIndex=0,chrono=null;
const labels={parcours:'Mon parcours',cartes:'Cartes mémo',quiz:'Quiz express',reperes:'Repères',sources:'Le livret & sources'};
function save(){state=P.changed(lastSaved,state,validIds);lastSaved=structuredClone(state);try{localStorage.setItem(P.key(accountId),JSON.stringify(state))}catch{storageOK=false}syncHeader();window.dispatchEvent(new Event('citoyen:progress'))}
function syncHeader(){$('#xp').textContent=`✦ ${state.done.length*20+state.known.length*5+state.best} points`;$('#english').setAttribute('aria-pressed',String(state.english));$('#english').classList.toggle('off',!state.english);$('#sync-status').textContent=!storageOK?'Stockage local indisponible':syncText||(accountId?'Compte connecté':'Progression sur cet appareil')}
function rememberLesson(){if(lessonState){state.resume={route:location.hash.slice(1)||'parcours',lessonId:lessonState.id,step:lessonState.step};save()}}
function add(key,id){if(!state[key].includes(id))state[key].push(id)}
function remove(key,id){state[key]=state[key].filter(x=>x!==id)}
function shuffle(items){let a=[...items];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',2600)}
function themeOptions(selected='all'){return `<option value="all">Tous les thèmes</option>${data.themes.map(t=>`<option value="${t.id}" ${selected===t.id?'selected':''}>${esc(t.short)}</option>`).join('')}`}
function sourceLink(l){return `<a class="source-link" href="${data.source}#page=${l.page}" target="_blank" rel="noopener">Livret officiel · p. ${l.page} ↗</a>`}
function translate(l){return state.english?`<div class="translation" lang="en"><b>IN ENGLISH</b>${esc(l.en)}</div>`:''}
function navigate(next,theme=null){if(!labels[next])next='parcours';if(quiz?.active&&next!=='quiz'){quiz=null}view=next;themeId=theme;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#breadcrumb').textContent=labels[view].toUpperCase();if(view==='cartes')resetDeck();render();main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})}
function route(){let h=location.hash.slice(1);if(h.startsWith('theme-')){let id=h.slice(6);if(data.themes.some(t=>t.id===id)){navigate('parcours',id);return}}navigate(labels[h]?h:'parcours')}
function go(v){if(location.hash==='#'+v)route();else location.hash=v}
function render(){syncHeader();if(view==='parcours')themeId?renderTheme():renderHome();if(view==='cartes')renderDeck();if(view==='quiz')quiz?renderQuiz():renderQuizSetup();if(view==='reperes')renderReperes();if(view==='sources')renderSources()}
function renderHome(){const next=data.lessons.find(l=>!state.done.includes(l.id))||data.lessons[0],first=next.id==='devise',percent=Math.round(state.done.length/data.lessons.length*100);main.innerHTML=`<div class="intro"><div><span class="eyebrow">VOTRE PARCOURS CITOYEN</span><h1>La citoyenneté,<br><em>ça s’apprend.</em></h1><p>Une idée à comprendre. Un petit pas de plus.</p></div><div class="progress-note"><div class="progress-ring" style="--progress:${percent}%" role="img" aria-label="${state.done.length} leçons terminées sur ${data.lessons.length}"><b>${percent}<small>%</small></b><span>${state.done.length}/${data.lessons.length} leçons</span></div></div></div><section class="featured"><div><span class="eyebrow">${state.done.length===data.lessons.length?'TOUT LE PARCOURS EST TERMINÉ':'VOTRE PROCHAINE DÉCOUVERTE'} · ${next.minutes} MIN</span><h2>${first?'Trois mots,<br>une République.':esc(next.title)}</h2><p>${esc(next.summary)}</p><button class="primary" onclick="openLesson('${next.id}')">${state.done.length?'Continuer mon parcours':'Commencer la leçon'} <span>↗</span></button></div><div class="word-stack"><button onclick="openLesson('devise')" aria-label="Découvrir la liberté">LIBERTÉ <span>↗</span></button><button onclick="openLesson('egalite')" aria-label="Découvrir l’égalité">ÉGALITÉ <span>=</span></button><button onclick="openLesson('fraternite')" aria-label="Découvrir la fraternité">FRATERNITÉ <span>✳</span></button><span class="tiny">CHOISISSEZ UN MOT POUR L’EXPLORER</span></div></section><div class="section-heading"><h2>Votre terrain de découverte</h2><span>5 thèmes · ${data.lessons.length} leçons</span></div><div class="theme-grid">${data.themes.map((t,i)=>{let ls=data.lessons.filter(l=>l.theme===t.id),n=ls.filter(l=>state.done.includes(l.id)).length;return `<button class="theme-card ${t.color}" onclick="go('theme-${t.id}')"><div class="card-top"><span class="theme-icon" aria-hidden="true">${t.icon}</span><span class="chapter">0${i+1}</span></div><h3>${esc(t.short)}</h3><p>${esc(t.description)}</p><div class="mini-progress" aria-hidden="true"><i style="width:${n/ls.length*100}%"></i></div><div class="card-bottom">${n}/${ls.length} leçons <span>${n===ls.length?'✓':'↗'}</span></div></button>`}).join('')}<button class="theme-card challenge-card" onclick="go('quiz')"><span class="eyebrow">À VOUS DE JOUER</span><h3>Un quiz pour<br>faire le point ?</h3><p>10 questions, des explications et le droit de se tromper.</p><div class="card-bottom">Lancer un quiz <span>↗</span></div></button></div>${state.review.length?`<section class="review-banner"><div><strong>${state.review.length} notion${state.review.length>1?'s':''} à revoir</strong><p>Vos hésitations deviennent votre prochaine étape.</p></div><button class="secondary" onclick="startReview()">Revoir mes cartes ↗</button></section>`:''}`}
function renderTheme(){const t=data.themes.find(x=>x.id===themeId),ls=data.lessons.filter(l=>l.theme===t.id),n=ls.filter(l=>state.done.includes(l.id)).length;main.innerHTML=`<button class="back" onclick="go('parcours')">← Tous les thèmes</button><span class="eyebrow">THÈME ${data.themes.indexOf(t)+1} · ${ls.length} LEÇONS</span><h1>${esc(t.name)}</h1><p class="page-subtitle">${esc(t.description)}</p><div class="theme-summary"><span>${n}/${ls.length} leçons terminées</span><a href="${data.source}#page=${ls[0].page}" target="_blank" rel="noopener">Livret · p. ${t.pages} ↗</a></div><div class="lesson-list">${ls.map((l,i)=>`<button onclick="openLesson('${l.id}')"><span class="lesson-number ${state.done.includes(l.id)?'done':''}">${state.done.includes(l.id)?'✓':String(i+1).padStart(2,'0')}</span><span class="lesson-label"><strong>${esc(l.title)}</strong><small>${esc(l.summary)}</small></span><span class="lesson-time">${l.minutes} min <span>↗</span></span></button>`).join('')}</div><button class="secondary" style="margin-top:24px" onclick="quizFilter='${t.id}';go('quiz')">S’entraîner sur ce thème ↗</button>`}
function openLesson(id){if(!validIds.has(id))return;lessonState={id,step:0,revealed:false,selected:null,checked:false};drawLesson();rememberLesson();if(!dialog.open)dialog.showModal()}
function lessonStep(step){if(!lessonState||step<0||step>2)return;lessonState.step=step;lessonState.selected=null;lessonState.checked=false;drawLesson();rememberLesson();dialog.scrollTop=0}
function drawLesson(){let s=lessonState,l=data.lessons.find(x=>x.id===s.id),done=state.done.includes(l.id);dialog.innerHTML=`<button class="close" aria-label="Fermer la leçon" onclick="dialog.close()">×</button><span class="eyebrow">${esc(l.tag)} · ${l.minutes} MIN</span><h2 id="lesson-title">${esc(l.title)}</h2><div class="lesson-steps" aria-label="Étapes de la leçon">${['Comprendre','Mémoriser','S’entraîner'].map((x,i)=>`<button class="${s.step===i?'active':''}" aria-current="${s.step===i?'step':'false'}" onclick="lessonStep(${i})"><span>${i+1}</span>${x}</button>`).join('')}</div>${s.step===0?`<p class="lead">${esc(l.summary)}</p><ul class="facts">${l.facts.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${translate(l)}<button class="primary solid" onclick="lessonStep(1)">C’est compris, on mémorise →</button>`:s.step===1?`<p class="muted">Prenez un instant pour trouver la réponse.</p><button class="flip-card small ${s.revealed?'flipped':''}" aria-pressed="${s.revealed}" onclick="lessonState.revealed=!lessonState.revealed;drawLesson()"><span class="eyebrow">${s.revealed?'À RETENIR':'LA QUESTION MÉMO'}</span><strong>${esc(s.revealed?l.answer:l.prompt)}</strong><span class="flip-hint">${s.revealed?'↶ Revoir la question':'↻ Révéler la réponse'}</span></button><button class="primary solid" onclick="lessonStep(2)">Passer à la question →</button>`:`<span class="exercise-label">EXERCICE PÉDAGOGIQUE · 1 RÉPONSE</span><h3 class="question">${esc(l.question)}</h3><div class="answers" role="group" aria-label="Choix de réponse">${l.choices.map((a,i)=>`<button class="answer ${s.selected===i?'selected':''} ${s.checked&&i===l.correct?'correct':''} ${s.checked&&s.selected===i&&i!==l.correct?'wrong':''}" ${s.checked?'disabled':''} aria-pressed="${s.selected===i}" onclick="lessonState.selected=${i};drawLesson()"><span>${'ABCD'[i]}</span>${esc(a)}${s.checked&&i===l.correct?'<b>✓</b>':''}</button>`).join('')}</div>${s.checked?`<div class="feedback ${s.selected===l.correct?'success':'retry'}" role="status"><strong>${s.selected===l.correct?'Bien joué !':'Une occasion d’apprendre.'}</strong><p>${esc(l.explanation)}</p></div>${translate(l)}${s.selected===l.correct?`<div class="completion"><span>✓ Leçon terminée${done?'':' · +20 points'}</span><button class="primary solid" onclick="nextLesson()">Leçon suivante →</button></div>`:`<button class="primary solid" onclick="lessonState.checked=false;lessonState.selected=null;drawLesson()">Réessayer →</button>`}`:`<button class="primary solid" ${s.selected===null?'disabled':''} onclick="checkLesson()">Vérifier ma réponse →</button>`}`}${sourceLink(l)}`}
function checkLesson(){const s=lessonState,l=data.lessons.find(x=>x.id===s.id);if(s.checked||s.selected===null)return;s.checked=true;if(s.selected===l.correct){let fresh=!state.done.includes(l.id);add('done',l.id);remove('review',l.id);save();if(fresh)toast('Une idée de plus à votre actif. +20 points')}else{add('review',l.id);save()}drawLesson()}
function nextLesson(){let index=data.lessons.findIndex(x=>x.id===lessonState.id);if(index<data.lessons.length-1)openLesson(data.lessons[index+1].id);else{dialog.close();go('parcours');toast('Bravo, vous êtes arrivé au bout du parcours !')}}
dialog.addEventListener('close',()=>{lessonState=null;render()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function resetDeck(){deck.ids=data.lessons.filter(l=>(deck.filter==='all'||l.theme===deck.filter)&&(!deck.reviewOnly||state.review.includes(l.id))).map(l=>l.id);deck.index=0;deck.flipped=false}
function startReview(){deck.reviewOnly=true;go('cartes')}
function renderDeck(){const l=data.lessons.find(x=>x.id===deck.ids[deck.index]);main.innerHTML=`<span class="eyebrow">RETROUVER L’IDÉE SANS REGARDER</span><h1>Une carte.<br><em>Un déclic.</em></h1><p class="page-subtitle">Essayez de répondre, puis retournez la carte.</p><div class="toolbar"><label>Thème <select id="deck-filter" onchange="deck.filter=this.value;resetDeck();renderDeck()">${themeOptions(deck.filter)}</select></label><button class="filter-pill ${deck.reviewOnly?'active':''}" aria-pressed="${deck.reviewOnly}" onclick="deck.reviewOnly=!deck.reviewOnly;resetDeck();renderDeck()">À revoir <span>${state.review.length}</span></button><button class="text-button" onclick="deck.ids=shuffle(deck.ids);deck.index=0;deck.flipped=false;renderDeck()">⇄ Mélanger</button></div>${!l?`<div class="empty-state"><span class="empty-icon">✓</span><h2>${deck.ids.length?'Série terminée !':'Aucune carte à revoir ici.'}</h2><p>${deck.ids.length?'Votre mémoire se renforce à chaque passage.':'Les notions manquées dans les quiz apparaissent dans cette liste.'}</p><button class="primary solid" onclick="deck.reviewOnly=false;resetDeck();renderDeck()">Voir toutes les cartes →</button></div>`:`<div class="deck-counter"><span>${esc(data.themes.find(t=>t.id===l.theme).short)}</span><span>CARTE ${deck.index+1} / ${deck.ids.length}</span></div><button class="flip-card ${deck.flipped?'flipped':''}" aria-pressed="${deck.flipped}" onclick="deck.flipped=!deck.flipped;renderDeck()"><span class="eyebrow">${deck.flipped?'À RETENIR':'EST-CE QUE VOUS VOUS SOUVENEZ ?'}</span><strong>${esc(deck.flipped?l.answer:l.prompt)}</strong><span class="flip-hint">${deck.flipped?'↶ Revoir la question':'↻ Retourner la carte'}</span></button>${deck.flipped?`${translate(l)}<div class="deck-actions"><button class="secondary" onclick="rateCard(false)">Encore à revoir</button><button class="primary solid" onclick="rateCard(true)">Je connais ✓</button></div>`:`<p class="deck-instruction">Cliquez sur la carte ou utilisez Entrée pour voir la réponse.</p>`}<div class="deck-bottom"><button class="text-button" ${deck.index===0?'disabled':''} onclick="deck.index--;deck.flipped=false;renderDeck()">← Précédente</button>${sourceLink(l)}<button class="text-button" onclick="deck.index++;deck.flipped=false;renderDeck()">Suivante →</button></div>`}`}
function rateCard(known){const id=deck.ids[deck.index];if(!id)return;if(known){add('known',id);remove('review',id)}else{add('review',id);remove('known',id)}save();deck.index++;deck.flipped=false;renderDeck()}
function quizCount(){return Math.min(10,data.lessons.filter(l=>quizFilter==='all'||l.theme===quizFilter).length)}
function renderQuizSetup(){main.innerHTML=`<span class="eyebrow">L’ERREUR FAIT PARTIE DU PARCOURS</span><h1>À vous <em>de jouer.</em></h1><p class="page-subtitle">Une courte série pour repérer ce que vous savez déjà.</p><section class="quiz-start"><div class="quiz-symbol" aria-hidden="true">✦</div><h2>Un quiz, de nouveaux repères.</h2><p>Des questions de connaissance et des situations concrètes. Après chaque réponse, découvrez pourquoi.</p><div class="quiz-facts"><span><b>${quizCount()}</b> questions</span><span><b>1</b> bonne réponse</span><span><b>∞</b> essais</span></div><label class="select-label" for="quiz-theme">Sur quel thème ?</label><select id="quiz-theme" onchange="quizFilter=this.value;renderQuizSetup()">${themeOptions(quizFilter)}</select><button class="primary solid" onclick="startQuiz()">C’est parti · ${quizCount()} questions →</button><p class="quiz-note">Quiz d’apprentissage créé pour ce site. Ce n’est pas une simulation complète de l’examen officiel.</p>${state.best?`<span class="best-score">Votre meilleur résultat : ${state.best}%</span>`:''}</section>`}
function startQuiz(){const pool=data.lessons.filter(l=>quizFilter==='all'||l.theme===quizFilter);quiz={active:true,items:shuffle(pool).slice(0,10).map(l=>({id:l.id,choices:shuffle(l.choices.map((text,i)=>({text,correct:i===l.correct})))})),index:0,selected:null,checked:false,results:[]};renderQuiz();main.focus({preventScroll:true})}
function renderQuiz(){if(!quiz)return renderQuizSetup();if(!quiz.active)return renderQuizResult();let q=quiz.items[quiz.index],l=data.lessons.find(x=>x.id===q.id);main.innerHTML=`<div class="quiz-top"><button class="back" onclick="quiz=null;renderQuizSetup()">← Quitter le quiz</button><span>QUESTION ${quiz.index+1} / ${quiz.items.length}</span></div><div class="quiz-progress" aria-label="${quiz.index} réponses sur ${quiz.items.length}">${quiz.items.map((x,i)=>`<span class="${i<quiz.index?(quiz.results[i].correct?'passed':'missed'):i===quiz.index?'current':''}"></span>`).join('')}</div><div class="quiz-question-panel"><span class="eyebrow">${esc(data.themes.find(t=>t.id===l.theme).short)}</span><h1 class="question">${esc(l.question)}</h1><p class="muted answer-instruction">Choisissez une seule réponse.</p><div class="answers" role="group" aria-label="Choix de réponse">${q.choices.map((a,i)=>`<button class="answer ${quiz.selected===i?'selected':''} ${quiz.checked&&a.correct?'correct':''} ${quiz.checked&&quiz.selected===i&&!a.correct?'wrong':''}" aria-pressed="${quiz.selected===i}" ${quiz.checked?'disabled':''} onclick="quiz.selected=${i};renderQuiz()"><span>${'ABCD'[i]}</span>${esc(a.text)}${quiz.checked&&a.correct?'<b>✓</b>':''}</button>`).join('')}</div>${quiz.checked?`<div class="feedback ${q.choices[quiz.selected].correct?'success':'retry'}" role="status"><strong>${q.choices[quiz.selected].correct?'Exactement !':'La bonne réponse est maintenant en vert.'}</strong><p>${esc(l.explanation)}</p></div>${translate(l)}${sourceLink(l)}<button class="primary solid" onclick="advanceQuiz()">${quiz.index===quiz.items.length-1?'Voir mon résultat':'Question suivante'} →</button>`:`<button class="primary solid" ${quiz.selected===null?'disabled':''} onclick="checkQuiz()">Vérifier →</button>`}</div>`}
function checkQuiz(){if(!quiz?.active||quiz.checked||quiz.selected===null)return;let item=quiz.items[quiz.index],correct=item.choices[quiz.selected].correct;quiz.checked=true;quiz.results.push({id:item.id,correct});if(!correct)add('review',item.id);else remove('review',item.id);save();renderQuiz()}
function advanceQuiz(){if(!quiz?.checked)return;quiz.index++;quiz.selected=null;quiz.checked=false;if(quiz.index===quiz.items.length){quiz.active=false;state.best=Math.max(state.best,Math.round(quiz.results.filter(x=>x.correct).length/quiz.items.length*100));save()}renderQuiz();main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})}
function renderQuizResult(){const good=quiz.results.filter(x=>x.correct).length,wrong=quiz.results.filter(x=>!x.correct);main.innerHTML=`<section class="quiz-result"><span class="eyebrow">SÉRIE TERMINÉE</span><div class="result-score">${good}<small>/${quiz.items.length}</small></div><h1>${wrong.length?'Chaque erreur vous fait avancer.':'Tout juste. Bien joué !'}</h1><p>${wrong.length?`${wrong.length} notion${wrong.length>1?'s':''} ajoutée${wrong.length>1?'s':''} à votre liste de révision.`:'Vous avez trouvé toutes les bonnes réponses de cette série.'}</p><div class="deck-actions"><button class="secondary" onclick="quiz=null;renderQuizSetup()">Choisir un thème</button><button class="primary solid" onclick="startQuiz()">Rejouer →</button></div></section>${wrong.length?`<div class="section-heading"><h2>Vos prochaines petites victoires</h2></div><div class="lesson-list">${wrong.map(x=>{let l=data.lessons.find(l=>l.id===x.id);return `<button onclick="openLesson('${l.id}')"><span class="lesson-label"><strong>${esc(l.title)}</strong><small>À retenir : ${esc(l.choices[l.correct])}</small></span><span class="lesson-time">Revoir ↗</span></button>`}).join('')}</div>`:''}<p class="quiz-note centered">Ce résultat concerne un quiz pédagogique. Il ne vaut pas attestation de réussite à un examen.</p>`}
function renderReperes(){main.innerHTML=`<span class="eyebrow">RELIEZ LES IDÉES</span><h1>Tout devient<br><em>plus clair.</em></h1><div class="segment" role="group" aria-label="Type de repère"><button class="${repereTab==='timeline'?'active':''}" aria-pressed="${repereTab==='timeline'}" onclick="repereTab='timeline';chrono=null;renderReperes()">La ligne du temps</button><button class="${repereTab==='institutions'?'active':''}" aria-pressed="${repereTab==='institutions'}" onclick="repereTab='institutions';renderReperes()">Qui fait quoi ?</button><button class="${repereTab==='chrono'?'active':''}" aria-pressed="${repereTab==='chrono'}" onclick="repereTab='chrono';chrono=null;renderReperes()">Défi chrono</button></div><div id="repere-body"></div>`;if(repereTab==='timeline')renderTimeline();else if(repereTab==='institutions')renderInstitutions();else if(chrono)renderChrono();else startChrono()}
function renderTimeline(){const e=data.timeline[eventIndex];$('#repere-body').innerHTML=`<p class="page-subtitle">Choisissez une date pour comprendre ce qu’elle a changé.</p><div class="timeline-layout"><div class="timeline-rail" role="group" aria-label="Dates historiques">${data.timeline.map((x,i)=>`<button class="${i===eventIndex?'active':''}" aria-pressed="${i===eventIndex}" onclick="eventIndex=${i};renderTimeline()"><b>${x[0]}</b><span>${esc(x[1])}</span></button>`).join('')}</div><article class="event-card"><span class="eyebrow">UN REPÈRE À RETENIR</span><div class="event-year">${e[0]}</div><h2>${esc(e[1])}</h2><p>${esc(e[2])}</p><a class="source-link" href="${data.source}#page=${e[3]}" target="_blank" rel="noopener">Livret · p. ${e[3]} ↗</a><div class="deck-bottom"><button class="text-button" ${eventIndex===0?'disabled':''} onclick="eventIndex--;renderTimeline()">← Avant</button><button class="text-button" ${eventIndex===data.timeline.length-1?'disabled':''} onclick="eventIndex++;renderTimeline()">Après →</button></div></article></div>`}
const institutions=[['Le président','Chef de l’État','Élu pour 5 ans. Nomme le Premier ministre.','president'],['Le Gouvernement','Conduit la politique de la Nation','Le Premier ministre dirige son action.','president'],['Le Parlement','Vote les lois','Assemblée nationale + Sénat. Contrôle le Gouvernement.','parlement'],['La justice','Tranche les litiges','Protège les droits et sanctionne les infractions.','justice'],['La commune','Écoles primaires et état civil','Le conseil municipal élit le maire.','territoires'],['Le département','Collèges et action sociale','Intervient aussi pour la protection de l’enfance.','territoires'],['La région','Lycées et transports régionaux','Intervient aussi pour la formation et l’économie.','territoires'],['Le préfet','Représente l’État','Il n’est pas le président du conseil départemental.','territoires'],['Les institutions européennes','Trois villes à retenir','Parlement : Strasbourg. Commission : Bruxelles. BCE : Francfort.','ue-symboles']];
function renderInstitutions(){$('#repere-body').innerHTML=`<p class="page-subtitle">Touchez une institution pour découvrir son rôle.</p><div class="institution-grid">${institutions.map((x,i)=>`<details class="institution"><summary><span class="chapter">${String(i+1).padStart(2,'0')}</span><h2>${esc(x[0])}</h2><span class="plus">+</span></summary><div><h3>${esc(x[1])}</h3><p>${esc(x[2])}</p><button class="text-button" onclick="openLesson('${x[3]}')">Ouvrir la leçon ↗</button></div></details>`).join('')}</div>`}
function startChrono(){repereTab='chrono';let events=shuffle(data.timeline).slice(0,4);chrono={items:shuffle(events),checked:false};if(!$('#repere-body'))renderReperes();else renderChrono()}
function renderChrono(){let correct=chrono.items.every((x,i)=>i===0||chrono.items[i-1][0]<x[0]);$('#repere-body').innerHTML=`<div class="chrono-intro"><h2>Remettez l’histoire dans l’ordre.</h2><p>Du plus ancien en haut au plus récent en bas. Utilisez les flèches pour déplacer les événements.</p></div><div class="chrono-list">${chrono.items.map((x,i)=>`<div><span class="lesson-number">${i+1}</span><strong>${esc(x[1])}${chrono.checked?`<small>${x[0]}</small>`:''}</strong><div class="move-buttons"><button aria-label="Monter ${esc(x[1])}" ${i===0||chrono.checked?'disabled':''} onclick="moveChrono(${i},-1)">↑</button><button aria-label="Descendre ${esc(x[1])}" ${i===3||chrono.checked?'disabled':''} onclick="moveChrono(${i},1)">↓</button></div></div>`).join('')}</div>${chrono.checked?`<div class="feedback ${correct?'success':'retry'}" role="status"><strong>${correct?'Vous avez le sens de l’histoire !':'Voici les dates pour vous aider.'}</strong><p>${correct?'Les quatre événements sont dans le bon ordre.':chrono.items.slice().sort((a,b)=>a[0]-b[0]).map(x=>x[0]+' : '+esc(x[1])).join(' → ')}</p></div><button class="primary solid" onclick="startChrono()">Un autre défi →</button>`:`<button class="primary solid" onclick="chrono.checked=true;renderChrono()">Vérifier l’ordre →</button>`}`}
function moveChrono(i,d){const j=i+d;if(j<0||j>=chrono.items.length||chrono.checked)return;[chrono.items[i],chrono.items[j]]=[chrono.items[j],chrono.items[i]];renderChrono()}
function renderSources(){main.innerHTML=`<span class="eyebrow">POUR APPROFONDIR ET VÉRIFIER</span><h1>Les bonnes<br><em>sources.</em></h1><p class="page-subtitle">Le livret officiel reste votre document de référence.</p><div class="source-intro"><h2>Comprendre le parcours</h2><p>Ce site propose ${data.lessons.length} leçons synthétiques, ${data.lessons.length} cartes mémo et des quiz originaux inspirés des cinq thèmes du livret. Il couvre les grands repères et renvoie aux pages à lire pour approfondir.</p><p>Il s’agit d’une adaptation indépendante : les exercices ne sont pas les questions officielles et ne constituent pas un examen blanc complet. La lecture du livret et la préparation de l’entretien de naturalisation restent complémentaires.</p><div class="exam-facts"><span><b>40</b> questions à l’examen</span><span><b>45 min</b> maximum</span><span><b>32/40</b> pour réussir</span></div><p class="source-note">Naturalisation et Carte de résident sont deux mentions distinctes. La réussite à l’examen Naturalisation ne remplace pas celle à l’examen Carte de résident. Les dispenses dépendent de votre situation.</p></div><div class="sources-grid">${data.sources.map(s=>`<a class="source-card" href="${s[2]}" target="_blank" rel="noopener"><span class="eyebrow">${esc(s[3])}</span><h2>${esc(s[0])}<span>↗</span></h2><p>${esc(s[1])}</p></a>`).join('')}</div><div class="local-note"><h2>Votre progression vous accompagne</h2><p>Sans compte, vos résultats restent dans ce navigateur. Avec un compte e-mail, ils sont synchronisés dans un espace privé. La déconnexion retire les données du compte de cet appareil. Consultez notre <a href="privacy.html">politique de confidentialité</a>.</p><p>Les explications anglaises sont des aides pédagogiques ; les examens se passent en français. Les références correspondent aux sources consultées le 13 septembre 2026.</p></div>`}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.view)));window.addEventListener('hashchange',route);$('#english').addEventListener('click',()=>{state.english=!state.english;save();lessonState?drawLesson():render();toast(state.english?'Aide en anglais activée':'Aide en anglais désactivée')});route();
// Progressive WebMCP enhancement; visible UI and tools use the same state and actions.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'read_learning_progress',title:'Lire la progression',description:'Read the current learner’s lesson completion and review progress without changing state.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({completed:state.done.length,total:data.lessons.length,toReview:state.review.length,knownCards:state.known.length})});register({name:'open_citizen_lesson',title:'Ouvrir une leçon',description:'Open a learning lesson in the visible dialog. This does not mark it as completed.',inputSchema:{type:'object',properties:{lessonId:{type:'string',enum:data.lessons.map(l=>l.id)}},required:['lessonId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input!=='object'||!validIds.has(input.lessonId)||Object.keys(input).some(k=>k!=='lessonId'))throw new Error('Unknown lessonId');openLesson(input.lessonId);return{opened:input.lessonId,step:'understand'}}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}


window.CitoyenLearning={
  validIds,
  snapshot:()=>P.clean(state,validIds),
  setSyncStatus:text=>{syncText=text;syncHeader()},
  getGuest:()=>{try{return P.clean(JSON.parse(localStorage.getItem(P.key(null))||'{}'),validIds)}catch{return P.clean({},validIds)}},
  switchAccount:(id,prior)=>{
    accountId=id;quiz=null;syncText='';
    if(dialog.open)dialog.close();
    try{if(prior&&prior!==id)localStorage.removeItem(P.key(prior));state=P.clean(JSON.parse(localStorage.getItem(P.key(id))||'{}'),validIds)}catch{state=P.clean({},validIds);storageOK=false}
    lastSaved=structuredClone(state);resetDeck();render();
  },
  replace:payload=>{
    state=P.clean(payload,validIds);lastSaved=structuredClone(state);
    try{localStorage.setItem(P.key(accountId),JSON.stringify(state))}catch{storageOK=false}
    syncHeader();if(!dialog.open&&!quiz?.active)render();
  },
  importGuest:()=>{state=P.merge(state,window.CitoyenLearning.getGuest(),validIds);save();render()},
  resume:()=>{const r=state.resume;if(r?.lessonId){const id=r.lessonId,step=r.step;go(r.route);openLesson(id);lessonStep(step)}else{go('parcours');toast('Choisissez une leçon pour commencer.')}}
};
